                    "sql": "create or replace table maplemonk.saadaa_inventory_sales_fact_items as with all_sku_dates AS ( SELECT DISTINCT c.date_day, upper(d.commonsku) as sku FROM maplemonk.saadaa_sales_consolidated AS d CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE \'2024-01-01\', CURRENT_DATE())) AS date_day ) AS c ), grn as ( select s.date_day grn_created_date, upper(s.sku) as sku, sum(ifnull(g.received_quantity,0)) inwarded_quantity from all_sku_dates s left join maplemonk.saadaa_grn_fact_items g on lower(g.sku) = lower(s.sku) and date_day = grn_created_date where s.sku is not null group by 1,2 ), total_grn as ( select grn_created_date, sum(received_quantity) inwarded_quantity from maplemonk.saadaa_grn_fact_items group by 1 ), sales as ( select date(order_date) order_date, commonsku, sum(ifnull(quantity,0)) sold_quantity from maplemonk.saadaa_sales_consolidated where marketplace like any (\'%AMAZON%\',\'%WEBSITE%\',\'%AMAZON_FBA%\',\'%MYNTRA PPMP%\',\'%CRED-API%\',\'%B2B%\',\'%SHOPIFY POS%\',\'%SHOPIFY1%\',\'%SHOPIFY%\',\'%ALLE%\',\'%OFFLINE%\') and warehouse in (\'SAADAA SUSTAINABLE DESIGNS AND TECHNOLOGIES PRIVATE LIMITED\',\'AMAZON_FBA_XIR6_AUTO\',\'HOLISOL - BLR\',\'EBO001\',\'HOLISOL-MH\') and (order_type is null or not(lower(order_type) like \'%stock%\')) group by 1,2 ), total_sales as ( select date(order_date) order_date, sum(ifnull(quantity,0)) sold_quantity from maplemonk.saadaa_sales_consolidated where marketplace like any (\'%AMAZON%\',\'%WEBSITE%\',\'%AMAZON_FBA%\',\'%MYNTRA PPMP%\',\'%CRED-API%\',\'%B2B%\',\'%SHOPIFY POS%\',\'%SHOPIFY1%\',\'%SHOPIFY%\',\'%ALLE%\',\'%OFFLINE%\') and warehouse in (\'SAADAA SUSTAINABLE DESIGNS AND TECHNOLOGIES PRIVATE LIMITED\',\'AMAZON_FBA_XIR6_AUTO\',\'HOLISOL - BLR\',\'EBO001\',\'HOLISOL-MH\') and (order_type is null or not(lower(order_type) like \'%stock%\')) group by 1 ) select g.grn_created_date, g.sku, sm.product_id, sm.product_name, sm.category, sm.size, sm.color, sm.item_category, sm.categorytype, sm.gender, sm.Product_Launch_Date, sm.Product_Variant, sm.Sub_category, g.inwarded_quantity, ifnull(s.sold_quantity,0) sold_quantity, tg.inwarded_quantity as total_inwarded_quantity, ifnull(ts.sold_quantity,0) total_sold_quantity from grn g left join total_grn tg on date(g.grn_created_date) = date(tg.grn_created_date) left join sales s on date(g.grn_created_date) = date(s.order_date) and lower(g.sku) = lower(s.commonsku) left join total_sales ts on date(g.grn_created_date) = date(ts.order_date) left join ( select commonsku, product_id, product_name, category, size, color, item_category, categorytype, gender, Product_Launch_Date, Product_Variant, Sub_category from `MAPLEMONK.saadaa_final_sku_master` qualify row_number() over (partition by commonsku order by 1) = 1 ) sm on lower(sm.commonsku) = lower(g.sku) ; create or replace table maplemonk.saadaa_isr_summary as select \"Last Day\" as period, avg(ifnull(total_sold_quantity,0)) total_sales, avg(ifnull(total_inwarded_quantity,0)) as total_grn, safe_divide(avg(ifnull(total_inwarded_quantity,0)),avg(ifnull(total_sold_quantity,0))) as ISR from maplemonk.saadaa_inventory_sales_fact_items where date(grn_created_date) = DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) group by 1 UNION ALL select \"Last Week\" as period, sum(total_sales) total_sales, sum(total_grn) total_grn, safe_divide(sum(total_grn),sum(total_sales)) as ISR from (select grn_created_date, avg(ifnull(total_sold_quantity,0)) total_sales, avg(ifnull(total_inwarded_quantity,0)) as total_grn, safe_divide(sum(ifnull(total_inwarded_quantity,0)),sum(ifnull(total_sold_quantity,0))) as ISR from maplemonk.saadaa_inventory_sales_fact_items where DATE(grn_created_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 6 DAY) AND DATE(grn_created_date) <= CURRENT_DATE() group by 1 ) group by 1 UNION ALL select \"MTD\" as period, sum(total_sales) total_sales, sum(total_grn) total_grn, safe_divide(sum(total_grn),sum(total_sales)) as ISR from ( select grn_created_date, avg(ifnull(total_sold_quantity,0)) total_sales, avg(ifnull(total_inwarded_quantity,0)) as total_grn, safe_divide(sum(ifnull(total_inwarded_quantity,0)),sum(ifnull(total_sold_quantity,0))) as ISR from maplemonk.saadaa_inventory_sales_fact_items where DATE_TRUNC(DATE(grn_created_date), MONTH) = DATE_TRUNC(CURRENT_DATE(), MONTH) group by 1 ) group by 1 ; create or replace table maplemonk.saadaa_inventory_by_warehouse as with daily_inventory_snapshot AS ( SELECT DATETIME_ADD(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',i.Report_Generated_Date), Interval 2 hour) DATA_FETCH_DATE, replace(replace(replace(replace(i.sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'`\',\'\') sku, case when location like \'%FBA%\' then \'FBA Warehouse\' when location = \'SAADAA SUSTAINABLE DESIGNS AND TECHNOLOGIES PRIVATE LIMITED\' then \'Main Warehouse\' when location = \'Holisol - BLR\' then \'Holisol - BLR\' when upper(location) = \'HOLISOL-MH\' then \'Holisol - MH\' end as Warehouse, sum(cast(Available_Quantity as INT64)) available_inventory FROM maplemonk.easyecom_saada_inventory_snapshot i where upper(location) <> \'EBO001\' group by 1,2,3 union all select DATE_SUB(cast(parse_date(\'%d-%m-%Y\', date) as date), INTERVAL 1 DAY) as date, replace(replace(replace(replace(replace(Sub_Category,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'`\',\'\'),\'\\'\',\'\') sku, \'Store\' AS warehouse, sum(cast(replace(Closing_Quantity,\'.00\',\'\') as INT64)) AS available_inventory from maplemonk.s3_Saadaa_store_daily_inventory where Sub_Category <> \'\' GROUP BY 1,2,3 ), all_sku_dates AS ( SELECT DISTINCT c.date_day, d.sku, d.warehouse, FROM daily_inventory_snapshot AS d CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE \'2024-01-01\', CURRENT_DATE())) AS date_day ) AS c ), daily_sales as ( SELECT CAST(order_date AS DATE) AS date_day, case when (marketplace in (\'AMAZON\',\'WEBSITE\',\'MYNTRA PPMP\',\'CRED-API\',\'B2B\') OR (UPPER(marketplace) = \'AMAZON_FBA\' and (upper(warehouse) = \'AMAZON_FBA_XIR6_AUTO\' or upper(warehouse) = \'SAADAA SUSTAINABLE DESIGNS AND TECHNOLOGIES PRIVATE LIMITED\'))) AND not(upper(warehouse) like any (\'HOLISOL - BLR\',\'HOLISOL-MH\')) then \'Main Warehouse\' when (lower(marketplace) like \'%fba%\' and (upper(warehouse) <> \'AMAZON_FBA_XIR6_AUTO\' or upper(warehouse) <> \'SAADAA SUSTAINABLE DESIGNS AND TECHNOLOGIES PRIVATE LIMITED\')) then \'FBA Warehouse\' when lower(warehouse) like \'%holisol - blr%\' then \'Holisol - BLR\' when lower(warehouse) like \'%holisol-mh%\' then \'Holisol - MH\' when upper(marketplace) = \'STORE\' then \'Store\' end as Warehouse, upper(replace(replace(replace(commonsku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\')) sku, SUM(quantity) AS daily_quantity FROM maplemonk.saadaa_sales_consolidated_intermediate WHERE (order_type IS NULL OR lower(order_type) NOT LIKE \'%stock transfer%\') and marketplace in (\'AMAZON\',\'WEBSITE\',\'MYNTRA PPMP\',\'AMAZON_FBA\',\'CRED-API\',\'B2B\',\'STORE\') and replace(replace(sku,\'-\',\'_\'),\'_\',\'\') is not null and (not(order_status = \'CANCELLED\' or oms_order_status = \'CANCELLED\') or order_status is null or oms_order_status is null) GROUP BY 1,2,3 ), inventory as ( select d.date_day, d.sku, d.warehouse, s.daily_quantity as sale_quantity, COALESCE(LAG(i.available_inventory, 1) OVER (PARTITION BY d.sku, d.warehouse ORDER BY d.date_day),0) AS opening_inventory, i.available_inventory as closing_inventory from all_sku_dates d left join daily_inventory_snapshot i on i.sku = d.sku and DATE_SUB(date(i.DATA_FETCH_DATE),INTERVAL 1 DAY) =d.date_day and upper(i.warehouse) = upper(d.warehouse) left join daily_sales s on lower(s.sku) = lower(d.sku) and d.date_day = s.date_day and (d.warehouse) = (s.warehouse) ), daily_warehouse_totals AS ( SELECT warehouse, date_day, DATE_TRUNC(date_day, MONTH) AS month_date, SUM(closing_inventory) AS total_closing_val FROM inventory GROUP BY 1, 2, 3 ), monthly_closing_snaps AS ( SELECT warehouse, month_date, total_closing_val AS month_closing_inventory FROM daily_warehouse_totals QUALIFY ROW_NUMBER() OVER ( PARTITION BY warehouse, month_date ORDER BY date_day DESC ) = 1 ), monthly_inventory as ( SELECT warehouse, month_date as month_first_day, LAG(month_closing_inventory) OVER ( PARTITION BY warehouse ORDER BY month_date ) AS month_opening_inventory, month_closing_inventory FROM monthly_closing_snaps ORDER BY warehouse, month_date ) select i.*, m.month_opening_inventory, m.month_closing_inventory from inventory i left join monthly_inventory m on m.warehouse = i.warehouse and date_trunc(i.date_day,month) = m.month_first_day ;",
